function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 10000) return 'arr needs 1 to 10000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 0 || v > 10000)) return 'Each value is a whole number from 0 to 10000.';
  return null;
}

