function validMountainArray(arr) {
  // Try every inner index as the peak and check both sides directly.
  for (let peak = 1; peak < arr.length - 1; peak++) {
    let ok = true;
    for (let k = 0; k < peak; k++) if (!(arr[k] < arr[k + 1])) ok = false;
    for (let k = peak; k < arr.length - 1; k++) if (!(arr[k] > arr[k + 1])) ok = false;
    if (ok) return true;
  }
  return false;
}

