function generate(rand, size) {
  const pick = (limit) => Math.floor(rand() * limit);
  const length = size === 'large' ? 1500 + pick(501) : 1 + pick(8);
  const step = size === 'large' ? 4 : 3;
  // A mountain: rising part, peak, falling part (either part may be empty).
  const upCount = pick(length);
  const downCount = length - 1 - upCount;
  const up = [];
  for (let k = 0; k < upCount; k++) up.push(k === 0 ? pick(4) : up[k - 1] + 1 + pick(step));
  const down = [];
  for (let k = 0; k < downCount; k++) down.unshift(k === 0 ? pick(4) : down[0] + 1 + pick(step));
  const peak = Math.max(up.length ? up[up.length - 1] : 0, down.length ? down[0] : 0) + 1 + pick(step);
  const arr = [...up, peak, ...down];
  const mode = pick(5);
  if (mode === 1 && arr.length > 1) {
    // A flat step somewhere.
    const at = pick(arr.length - 1);
    arr[at + 1] = arr[at];
  } else if (mode === 2 && arr.length > 2) {
    // A small bump that may add a second hill.
    const at = 1 + pick(arr.length - 2);
    arr[at] = Math.min(10000, arr[at] + pick(3 * step));
  } else if (mode === 3 && size === 'small') {
    // Unstructured values.
    for (let k = 0; k < arr.length; k++) arr[k] = pick(5);
  }
  return [arr];
}
